parameters.jsCode:
const rows = $input.all();
const summary = rows.map(r => r.json);

const totalRevenue = summary.reduce((s, r) => s + Number(r.revenue_this_week || 0), 0);
const totalDeals = summary.reduce((s, r) => s + Number(r.deals_closed || 0), 0);
const totalInvoices = summary.reduce((s, r) => s + Number(r.invoices_sent || 0), 0);
const totalTasks = summary.reduce((s, r) => s + Number(r.tasks_completed || 0), 0);

const weeklyContext = {
  week_ending: new Date().toISOString().split('T')[0],
  total_revenue: totalRevenue,
  total_deals_closed: totalDeals,
  total_invoices_sent: totalInvoices,
  total_tasks_completed: totalTasks,
  by_company: summary
};

return [{ json: weeklyContext }];

